/**
 * CURATED QUEST CATALOGUE (demo mode copy). These quests are written by hand, not generated by a model.
 * The source of truth is backend/part3/data/quests.json; scripts/sync_catalog.py copies it here and a
 * backend test fails if the two drift apart. When the backend is connected, GET /api/quests replaces this.
 */
import { parseQuest } from '../services/validators';
import type { Quest } from '../types';
import raw from './quests.curated.json';

export type QuestSeed = Omit<Quest, 'status' | 'completedAt' | 'startedAt' | 'completionCount'>;

export const MOCK_QUESTS: QuestSeed[] = (raw as unknown[])
  .map(parseQuest)
  .filter((q): q is Quest => q !== null)
  .map(({ status: _s, completedAt: _c, startedAt: _st, completionCount: _n, ...seed }) => ({ ...seed, origin: 'curated' as const }));
